// [S4] Family appointments — stat chips, mutually exclusive Upcoming / Requests / Past
// tabs, member filter and sort, expandable cards with a date box. Mirrors web AppointmentsPage.
import 'package:family_veda/models/appointment.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/theme/app_theme.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:intl/intl.dart';

enum AppointmentTab { upcoming, requests, past }

/// Every appointment lands in exactly one tab, so the counts add up.
AppointmentTab appointmentTabFor(Appointment item, DateTime now) {
  final future = !item.startsAt.isBefore(now);
  if (future && item.status == AppointmentStatus.confirmed) {
    return AppointmentTab.upcoming;
  }
  if (future && item.status == AppointmentStatus.requested) {
    return AppointmentTab.requests;
  }
  return AppointmentTab.past;
}

class AppointmentsScreen extends ConsumerStatefulWidget {
  const AppointmentsScreen({super.key});

  @override
  ConsumerState<AppointmentsScreen> createState() => _AppointmentsScreenState();
}

class _AppointmentsScreenState extends ConsumerState<AppointmentsScreen> {
  AppointmentTab _tab = AppointmentTab.upcoming;
  String _memberFilter = 'all';
  bool _soonestFirst = true;
  String? _expandedId;

  Future<void> _cancel(String id) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Cancel Appointment'),
        content: const Text('Are you sure you want to cancel this appointment?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: const Text('Keep'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            style: ElevatedButton.styleFrom(backgroundColor: AppColors.danger),
            child: const Text('Cancel Visit', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );

    if (confirmed != true || !mounted) return;

    try {
      await ref.read(familyPortalApiProvider).cancelAppointment(id);
      ref.invalidate(myAppointmentsProvider);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Appointment cancelled.'),
            backgroundColor: AppColors.success,
          ),
        );
      }
    } on Object {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not cancel the appointment. Try again.'),
            backgroundColor: AppColors.danger,
          ),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final appointmentsAsync = ref.watch(myAppointmentsProvider);
    final doctor = ref.watch(familyDashboardProvider).valueOrNull?.familyDoctor;
    final isDark = Theme.of(context).brightness == Brightness.dark;

    return Scaffold(
      backgroundColor: Colors.transparent,
      floatingActionButton: FloatingActionButton.extended(
        onPressed: () => context.push('/appointments/book'),
        icon: const Icon(Icons.add_rounded, size: 20),
        label: const Text('Book', style: TextStyle(fontWeight: FontWeight.w700)),
        backgroundColor: isDark ? AppColors.primaryDark : AppColors.primary,
        foregroundColor: Colors.white,
      ),
      body: SafeArea(
        child: appointmentsAsync.when(
          loading: () => const LoadingStateView(label: 'Loading appointments'),
          error: (_, _) => ErrorRetryView(
            onRetry: () => ref.invalidate(myAppointmentsProvider),
          ),
          data: (items) {
            final now = DateTime.now();
            final counts = {for (final t in AppointmentTab.values) t: 0};
            for (final a in items) {
              final t = appointmentTabFor(a, now);
              counts[t] = counts[t]! + 1;
            }
            final completed =
                items.where((a) => a.status == AppointmentStatus.completed).length;
            final members = <String, String>{
              for (final a in items) a.memberId: a.memberDisplayName,
            };
            if (_memberFilter != 'all' && !members.containsKey(_memberFilter)) {
              _memberFilter = 'all';
            }
            final visible = items
                .where((a) => appointmentTabFor(a, now) == _tab)
                .where((a) => _memberFilter == 'all' || a.memberId == _memberFilter)
                .toList()
              ..sort(
                (a, b) => _soonestFirst
                    ? a.startsAt.compareTo(b.startsAt)
                    : b.startsAt.compareTo(a.startsAt),
              );

            return RefreshIndicator(
              onRefresh: () async => ref.invalidate(myAppointmentsProvider),
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(
                  parent: BouncingScrollPhysics(),
                ),
                padding: const EdgeInsets.fromLTRB(16, 12, 16, 96),
                children: [
                  _Hero(isDark: isDark),
                  const SizedBox(height: 14),
                  _StatGrid(
                    isDark: isDark,
                    stats: [
                      _Stat('Upcoming', '${counts[AppointmentTab.upcoming]}',
                          isDark ? AppColors.primaryDark : AppColors.primary),
                      _Stat('Awaiting doctor', '${counts[AppointmentTab.requests]}',
                          isDark ? AppColors.warningDark : AppColors.warning),
                      _Stat('Completed', '$completed',
                          isDark ? AppColors.successDark : AppColors.success),
                      _Stat('Family doctor', doctor?.displayName ?? 'Not assigned',
                          isDark ? AppColors.primaryLumDark : AppColors.primaryLum),
                    ],
                  ),
                  const SizedBox(height: 16),
                  Text(
                    'My appointments',
                    style: TextStyle(
                      fontSize: 17,
                      fontWeight: FontWeight.w800,
                      color: isDark ? AppColors.textHeadingDark : AppColors.textHeading,
                    ),
                  ),
                  const SizedBox(height: 10),
                  SegmentedButton<AppointmentTab>(
                    showSelectedIcon: false,
                    segments: [
                      ButtonSegment(
                        value: AppointmentTab.upcoming,
                        label: Text('Upcoming ${counts[AppointmentTab.upcoming]}'),
                      ),
                      ButtonSegment(
                        value: AppointmentTab.requests,
                        label: Text('Requests ${counts[AppointmentTab.requests]}'),
                      ),
                      ButtonSegment(
                        value: AppointmentTab.past,
                        label: Text('Past ${counts[AppointmentTab.past]}'),
                      ),
                    ],
                    selected: {_tab},
                    onSelectionChanged: (s) => setState(() {
                      _tab = s.first;
                      _expandedId = null;
                    }),
                  ),
                  const SizedBox(height: 10),
                  Row(
                    children: [
                      Expanded(
                        child: DropdownButtonFormField<String>(
                          key: ValueKey('member-filter-$_memberFilter'),
                          initialValue: _memberFilter,
                          isExpanded: true,
                          decoration: const InputDecoration(
                            labelText: 'Member',
                            isDense: true,
                            border: OutlineInputBorder(),
                          ),
                          items: [
                            const DropdownMenuItem(
                              value: 'all',
                              child: Text('All members'),
                            ),
                            for (final e in members.entries)
                              DropdownMenuItem(
                                value: e.key,
                                child: Text(e.value, overflow: TextOverflow.ellipsis),
                              ),
                          ],
                          onChanged: (v) => setState(() => _memberFilter = v ?? 'all'),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Tooltip(
                        message: _soonestFirst ? 'Earliest first' : 'Latest first',
                        child: OutlinedButton.icon(
                          onPressed: () => setState(() => _soonestFirst = !_soonestFirst),
                          icon: Icon(
                            _soonestFirst ? Icons.arrow_upward : Icons.arrow_downward,
                            size: 16,
                          ),
                          label: Text(_soonestFirst ? 'Earliest' : 'Latest'),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  if (visible.isEmpty)
                    _EmptyCard(isDark: isDark, hasAny: items.isNotEmpty)
                  else
                    ...visible.map(
                      (item) => _AppointmentCard(
                        item: item,
                        isDark: isDark,
                        expanded: _expandedId == item.id,
                        onToggle: () => setState(
                          () => _expandedId = _expandedId == item.id ? null : item.id,
                        ),
                        onCancel: () => _cancel(item.id),
                      ),
                    ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

