class _Stat {
  const _Stat(this.label, this.value, this.accent);
  final String label;
  final String value;
  final Color accent;
}

class _StatGrid extends StatelessWidget {
  const _StatGrid({required this.stats, required this.isDark});
  final List<_Stat> stats;
  final bool isDark;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final columns = constraints.maxWidth >= 600 ? 4 : 2;
        final width = (constraints.maxWidth - (columns - 1) * 10) / columns;
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          children: [
            for (final s in stats)
              SizedBox(
                width: width,
                child: Container(
                  padding: const EdgeInsets.fromLTRB(12, 10, 10, 10),
                  decoration: BoxDecoration(
                    color: isDark ? AppColors.surfaceDark : AppColors.surface,
                    borderRadius: BorderRadius.circular(12),
                    border: Border(
                      left: BorderSide(color: s.accent, width: 4),
                      top: BorderSide(color: isDark ? AppColors.borderDark : AppColors.border),
                      right: BorderSide(color: isDark ? AppColors.borderDark : AppColors.border),
                      bottom: BorderSide(color: isDark ? AppColors.borderDark : AppColors.border),
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        s.label.toUpperCase(),
                        style: TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.w700,
                          letterSpacing: 0.4,
                          color: isDark ? AppColors.mutedDark : AppColors.muted,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        s.value,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          fontSize: s.value.length > 4 ? 14 : 22,
                          fontWeight: FontWeight.w800,
                          color: isDark ? AppColors.textHeadingDark : AppColors.textHeading,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
          ],
        );
      },
    );
  }
}

