class _AppointmentCard extends StatelessWidget {
  const _AppointmentCard({
    required this.item,
    required this.isDark,
    required this.expanded,
    required this.onToggle,
    required this.onCancel,
  });

  final Appointment item;
  final bool isDark;
  final bool expanded;
  final VoidCallback onToggle;
  final VoidCallback onCancel;

  Color get _accent => switch (item.status) {
    AppointmentStatus.confirmed => isDark ? AppColors.primaryDark : AppColors.primary,
    AppointmentStatus.requested => isDark ? AppColors.warningDark : AppColors.warning,
    AppointmentStatus.completed => isDark ? AppColors.successDark : AppColors.success,
    _ => isDark ? AppColors.mutedDark : AppColors.muted,
  };

  @override
  Widget build(BuildContext context) {
    final muted = isDark ? AppColors.mutedDark : AppColors.muted;
    final primary = isDark ? AppColors.primaryDark : AppColors.primary;
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      decoration: BoxDecoration(
        color: isDark ? AppColors.surfaceDark : AppColors.surface,
        borderRadius: BorderRadius.circular(14),
        border: Border(
          left: BorderSide(color: _accent, width: 4),
          top: BorderSide(color: isDark ? AppColors.borderDark : AppColors.border),
          right: BorderSide(color: isDark ? AppColors.borderDark : AppColors.border),
          bottom: BorderSide(color: isDark ? AppColors.borderDark : AppColors.border),
        ),
      ),
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  width: 56,
                  padding: const EdgeInsets.symmetric(vertical: 8),
                  decoration: BoxDecoration(
                    color: isDark ? AppColors.primarySubtleDark : AppColors.primarySubtle,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Column(
                    children: [
                      Text(
                        '${item.startsAt.day}',
                        style: TextStyle(fontSize: 20, fontWeight: FontWeight.w800, color: primary),
                      ),
                      Text(
                        DateFormat('MMM').format(item.startsAt).toUpperCase(),
                        style: TextStyle(fontSize: 10, fontWeight: FontWeight.w700, color: primary),
                      ),
                      Text(
                        DateFormat('EEE').format(item.startsAt).toUpperCase(),
                        style: TextStyle(fontSize: 10, color: primary),
                      ),
                    ],
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        item.memberDisplayName,
                        style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w700),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        item.doctor?.displayName ?? 'Family doctor',
                        style: TextStyle(fontSize: 12.5, color: muted),
                      ),
                      Text(
                        '${DateFormat.jm().format(item.startsAt)} · ${item.durationMinutes} min',
                        style: TextStyle(fontSize: 12.5, color: muted),
                      ),
                      const SizedBox(height: 6),
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                        decoration: BoxDecoration(
                          color: _accent.withValues(alpha: 0.14),
                          borderRadius: BorderRadius.circular(999),
                        ),
                        child: Text(
                          item.status.friendlyLabel,
                          style: TextStyle(fontSize: 11, fontWeight: FontWeight.w700, color: _accent),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
            if (expanded) ...[
              const SizedBox(height: 10),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: isDark ? AppColors.surfaceSubtleDark : AppColors.surfaceSubtle,
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    _detail('Reason', item.reason.isEmpty ? '—' : item.reason, muted),
                    _detail('Duration', '${item.durationMinutes} minutes', muted),
                    _detail(
                      "Doctor's note",
                      (item.doctorNote?.isNotEmpty ?? false) ? item.doctorNote! : 'No note yet',
                      muted,
                    ),
                  ],
                ),
              ),
            ],
            const SizedBox(height: 8),
            Align(
              alignment: Alignment.centerRight,
              child: Wrap(
              spacing: 8,
              children: [
                TextButton(onPressed: onToggle, child: Text(expanded ? 'Hide' : 'View')),
                if (item.status.isCancellable)
                  TextButton(
                    onPressed: onCancel,
                    style: TextButton.styleFrom(
                      foregroundColor: isDark ? AppColors.dangerDark : AppColors.danger,
                    ),
                    child: const Text('Cancel'),
                  ),
              ],
            ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _detail(String label, String value, Color muted) => Padding(
    padding: const EdgeInsets.only(bottom: 6),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          label.toUpperCase(),
          style: TextStyle(fontSize: 10, fontWeight: FontWeight.w700, color: muted),
        ),
        Text(value, style: const TextStyle(fontSize: 13)),
      ],
    ),
  );
}
